--------------------------------------------------------
--  DDL for View ACTIVIDADES_DE_CALENDARIO_PROYECTO_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "ACTIVIDADES_DE_CALENDARIO_PROYECTO_VIEW" ("ID_EVENTO", "TITULO_ACTIVIDAD", "DETALLE_REALIZADO", "FECHA_HORA_INICIO", "FECHA_HORA_FIN", "CLASE_CSS") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT 
    lar.actividad_id                      AS id_evento,
    cad.descripcion                       AS titulo_actividad,
    lar.actividad_realizada               AS detalle_realizado,
    -- Determinamos la fecha/hora de inicio. Si HORA_INICIO está vacía, usamos la FECHA_INICIO del cronograma
    COALESCE(cad.hora_inicio, CAST(ca.fecha_inicio AS TIMESTAMP)) AS fecha_hora_inicio,
    -- Determinamos la fecha/hora de fin. Si HORA_FIN está vacía, usamos la FECHA_FIN del cronograma
    COALESCE(cad.hora_fin, CAST(ca.fecha_fin AS TIMESTAMP))    AS fecha_hora_fin,
    -- Clase CSS opcional por si quieres aplicar colores a los bloques de actividades
    'actividad-cronograma-style'          AS clase_css
FROM libro_obra_actividades_realizadas lar
INNER JOIN cronogra_actividades_detalles cad 
    ON lar.actividad_id_cronograma = cad.actividad_id
INNER JOIN cronograma_actividades ca 
    ON cad.cronograma_id = ca.cronograma_id
--WHERE ca.proyecto_id = :P19_PROYECTO_ID -- Reemplaza por tu ítem real de Proyecto
;
--------------------------------------------------------
--  DDL for View CRONOGRAMA_CONTRATO_ACTIVIDADES_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "CRONOGRAMA_CONTRATO_ACTIVIDADES_VIEW" ("PROYECTO_ID", "NOMBRE_PROYECTO", "MONTO", "FECHA_CREACION", "FECHA_INICIO_EJECUCION", "FECHA_FIN_PROYECTO", "RESPONSABLE_ID", "TIPO_PROYECTO_ID", "NOMBRE_TIPO_PROYECTO", "CONTRATO_ID", "ANTICIPO_VALOR", "FECHA_CONTRATO", "FECHA_FIN_CONTRATO", "TIEMPO_MESES", "CONTRATISTA", "ADMINISTRADOR", "FISCALIZADOR", "FECHA_INICIO", "FECHA_FIN", "DESCRIPCION", "HORA_INICIO", "HORA_FIN", "MONTO_ACTIVIDAD", "SOLICITUD_PROYECTO_ID", "NOMBRE_TIPO_PROYECTO1", "TIPO_PROYECTO_ID1", "SECTOR_ID", "NOMBRE_SECTOR", "ACTIVIDAD_ID", "CRONOGRAMA_ID", "DESCRIPCION1", "HORA_INICIO1", "HORA_FIN1", "MONTO1", "ESTADO_CONFIGURADO_ID", "COMENTARIO", "PERSONAL_ID", "APELLIDOS", "NOMBRES", "PERSONAL_ID1", "APELLIDOS1", "NOMBRES1", "PERSONAL_ID2", "APELLIDOS2", "NOMBRES2", "NRO_CEDULA", "NRO_CEDULA1", "NRO_CEDULA2", "SEXO") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    cc.proyecto_id,
    proyecto.nombre_proyecto,
    proyecto.monto,
    proyecto.fecha_creacion,
    proyecto.fecha_inicio_ejecucion,
    proyecto.fecha_fin_ejecucion                         AS fecha_fin_proyecto,
    proyecto.responsable_id,
    solicitud_proyecto.tipo_proyecto_id,
    nombre_tipo_proyecto,
    contrato.contrato_id,
    proyecto.anticipo_valor,
    contrato.fecha_contrato,
    contrato.fecha_fin                                   AS fecha_fin_contrato,
    contrato.tiempo_meses,
    cont.apellidos
    || ' '
    || cont.nombres                                      AS contratista,
    adm.apellidos
    || ' '
    || adm.nombres                                       AS administrador,
    fis.apellidos
    || ' '
    || fis.nombres                                       AS fiscalizador,
    cc.fecha_inicio,
    cc.fecha_fin,
    cca.descripcion,
    cca.hora_inicio,
    cca.hora_fin,
    cca.monto                                            AS monto_actividad,
    gproy_elel.solicitud_proyecto.solicitud_proyecto_id,
    gproy_elel.tipo_proyecto.nombre_tipo_proyecto        AS nombre_tipo_proyecto1,
    gproy_elel.tipo_proyecto.tipo_proyecto_id            AS tipo_proyecto_id1,
    gproy_elel.sector.sector_id,
    gproy_elel.sector.nombre_sector,
    gproy_elel.cronogra_actividades_detalles.actividad_id,
    gproy_elel.cronogra_actividades_detalles.cronograma_id,
    gproy_elel.cronogra_actividades_detalles.descripcion AS descripcion1,
    gproy_elel.cronogra_actividades_detalles.hora_inicio AS hora_inicio1,
    gproy_elel.cronogra_actividades_detalles.hora_fin    AS hora_fin1,
    gproy_elel.cronogra_actividades_detalles.monto       AS monto1,
    cc.estado_configurado_id,
    cc.comentario,
    fis.personal_id,
    fis.apellidos,
    fis.nombres,
    adm.personal_id                                      AS personal_id1,
    adm.apellidos                                        AS apellidos1,
    adm.nombres                                          AS nombres1,
    cont.personal_id                                     AS personal_id2,
    cont.apellidos                                       AS apellidos2,
    cont.nombres                                         AS nombres2,
    cont.nro_cedula,
    fis.nro_cedula                                       AS nro_cedula1,
    adm.nro_cedula                                       AS nro_cedula2,
    cont.sexo
FROM
         proyecto
    INNER JOIN contrato ON proyecto.proyecto_id = contrato.proyecto_id
    INNER JOIN personal_obra                 cont ON cont.personal_id = contrato.contratista_id
    INNER JOIN personal_obra                 adm ON adm.personal_id = contrato.administrador_id
    RIGHT JOIN cronograma_actividades        cc ON cc.proyecto_id = proyecto.proyecto_id
    INNER JOIN oferta                        ON oferta.oferta_id=proyecto.oferta_id
    INNER JOIN cronogra_actividades_detalles cca ON cca.cronograma_id = cc.cronograma_id
    INNER JOIN gproy_elel.solicitud_proyecto ON oferta.solicitud_proyecto_id = gproy_elel.solicitud_proyecto.solicitud_proyecto_id
    INNER JOIN gproy_elel.sector ON gproy_elel.solicitud_proyecto.sector_id = gproy_elel.sector.sector_id
    INNER JOIN gproy_elel.tipo_proyecto ON gproy_elel.solicitud_proyecto.tipo_proyecto_id = gproy_elel.tipo_proyecto.tipo_proyecto_id
    INNER JOIN gproy_elel.cronogra_actividades_detalles ON gproy_elel.cronogra_actividades_detalles.cronograma_id = cc.cronograma_id
    INNER JOIN personal_obra                 fis ON contrato.fiscalizador_id = fis.personal_id
ORDER BY
    contrato.fecha_contrato DESC
;
