--------------------------------------------------------
--  DDL for View CRONOGRAMA_CONTRATO_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "CRONOGRAMA_CONTRATO_VIEW" ("PROYECTO_ID", "NOMBRE_PROYECTO", "MONTO", "FECHA_INICIO_EJECUCION", "FECHA_FIN_EJECUCION", "CRONOGRAMA_ID", "FECHA_INICIO", "FECHA_FIN", "COMENTARIO", "OFERTA_ID", "SOLICITUD_PROYECTO_ID", "ESTADO_ID", "NOMBRE_ESTADOS", "SECTOR_ID", "NOMBRE_SECTOR", "TIPO_PROYECTO_ID", "NOMBRE_TIPO_PROYECTO", "EMPRESA_ID", "NOMBRE_EMPRESA", "RUC") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    gproy_elel.proyecto.proyecto_id,
    gproy_elel.proyecto.nombre_proyecto,
    gproy_elel.proyecto.monto,
    gproy_elel.proyecto.fecha_inicio_ejecucion,
    gproy_elel.proyecto.fecha_fin_ejecucion,
    gproy_elel.cronograma_actividades.cronograma_id,
    gproy_elel.cronograma_actividades.fecha_inicio,
    gproy_elel.cronograma_actividades.fecha_fin,
    gproy_elel.cronograma_actividades.comentario,
    gproy_elel.proyecto.oferta_id,
    gproy_elel.solicitud_proyecto.solicitud_proyecto_id,
    gproy_elel.estados_configurados.estado_id,
    gproy_elel.estados_configurados.nombre_estados,
    gproy_elel.sector.sector_id,
    gproy_elel.sector.nombre_sector,
    gproy_elel.tipo_proyecto.tipo_proyecto_id,
    gproy_elel.tipo_proyecto.nombre_tipo_proyecto,
    gproy_elel.empesas_solicitantes.empresa_id,
    gproy_elel.empesas_solicitantes.nombre_empresa,
    gproy_elel.empesas_solicitantes.ruc
FROM
         gproy_elel.cronograma_actividades
    INNER JOIN gproy_elel.proyecto ON gproy_elel.cronograma_actividades.proyecto_id = gproy_elel.proyecto.proyecto_id
    INNER JOIN gproy_elel.oferta ON gproy_elel.proyecto.oferta_id = gproy_elel.oferta.oferta_id
    INNER JOIN gproy_elel.solicitud_proyecto ON gproy_elel.oferta.solicitud_proyecto_id = gproy_elel.solicitud_proyecto.solicitud_proyecto_id
    INNER JOIN gproy_elel.estados_configurados ON gproy_elel.proyecto.estado_proyecto_id = gproy_elel.estados_configurados.estado_id
    INNER JOIN gproy_elel.sector ON gproy_elel.solicitud_proyecto.sector_id = gproy_elel.sector.sector_id
    INNER JOIN gproy_elel.tipo_proyecto ON gproy_elel.solicitud_proyecto.tipo_proyecto_id = gproy_elel.tipo_proyecto.tipo_proyecto_id
    INNER JOIN gproy_elel.empesas_solicitantes ON gproy_elel.solicitud_proyecto.empresa_id = gproy_elel.empesas_solicitantes.empresa_id
;
--------------------------------------------------------
--  DDL for View DASHBOAR_PANEL_AVANCES_OBRA_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "DASHBOAR_PANEL_AVANCES_OBRA_VIEW" ("PROYECTO_ID", "NOMBRE_PROYECTO", "NOMBRE_TIPO_PROYECTO", "NOMBRE_SECTOR", "MONTO_PRESUPUESTADO", "MONTO_EJECUTADO", "SALDO_PENDIENTE", "PCT_AVANCE_FINANCIERO", "FECHA_INICIO_EJECUCION", "FECHA_FIN_EJECUCION", "DIAS_RESTANTES", "ESTADO_PROYECTO") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  WITH summary_planillas AS (
    -- Pre-agregación de planillas por contrato para evitar multiplicidad de filas en JOINs
    SELECT 
        c.proyecto_id,
        NVL(SUM(p.monto_total), 0) AS total_ejecutado_planillas,
        COUNT(p.planilla_id)        AS total_planillas_generadas
    FROM contrato c
    JOIN planilla_contractual p ON p.contrato_id = c.contrato_id
    -- Opcional: Filtrar por estados aprobados de planilla (p.estado_id)
    GROUP BY c.proyecto_id
)
SELECT 
    p.proyecto_id,
    p.nombre_proyecto,
    tp.nombre_tipo_proyecto,
    sec.nombre_sector,
    p.monto                                 AS monto_presupuestado,
    NVL(sp.total_ejecutado_planillas, 0)    AS monto_ejecutado,
    (p.monto - NVL(sp.total_ejecutado_planillas, 0)) AS saldo_pendiente,
    
    -- Porcentaje de avance financiero (evitando división por cero)
    CASE 
        WHEN p.monto > 0 THEN ROUND((NVL(sp.total_ejecutado_planillas, 0) / p.monto) * 100, 2)
        ELSE 0 
    END AS pct_avance_financiero,

    -- Cálculos temporales
    p.fecha_inicio_ejecucion,
    p.fecha_fin_ejecucion,
    CASE 
        WHEN p.fecha_fin_ejecucion > SYSDATE THEN ROUND(p.fecha_fin_ejecucion - SYSDATE)
        ELSE 0 
    END AS dias_restantes,

    ec.nombre_estados                       AS estado_proyecto
FROM proyecto p
JOIN oferta o                  ON p.oferta_id = o.oferta_id
JOIN solicitud_proyecto sp_sol ON o.solicitud_proyecto_id = sp_sol.solicitud_proyecto_id
LEFT JOIN tipo_proyecto tp     ON sp_sol.tipo_proyecto_id = tp.tipo_proyecto_id
LEFT JOIN sector sec           ON sp_sol.sector_id = sec.sector_id
LEFT JOIN estados_configurados ec ON p.estado_proyecto_id = ec.estado_id
LEFT JOIN summary_planillas sp ON p.proyecto_id = sp.proyecto_id
/*WHERE (:P10_TIPO_PROYECTO_ID IS NULL OR sp_sol.tipo_proyecto_id = :P10_TIPO_PROYECTO_ID)
  AND (:P10_SECTOR_ID IS NULL OR sp_sol.sector_id = :P10_SECTOR_ID)
  AND (:P10_ESTADO_ID IS NULL OR p.estado_proyecto_id = :P10_ESTADO_ID)*/
;
--------------------------------------------------------
--  DDL for View EMPRESAS_SOLICITANTES_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "EMPRESAS_SOLICITANTES_VIEW" ("EMPRESA_ID", "NOMBRE_EMPRESA", "RUC", "SECTOR_ID", "ACTIVIDADES_PRINCIPLAES", "REP_LEGAL", "NRO_IDENTIDAD", "TIPO_IDENTIDAD_REPRESENTANTE", "CANTON_ID", "NOMBRE_CIUDAD", "DIRECCION", "ESTADO_EMPRESA", "INFO_ADICIONAL") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    empresa_id,
    nombre_empresa,
    ruc,
    sector_id,
    actividades_principlaes,
    rep_legal,
    nro_identidad,
    tipo_identidad_representante,
    canton_id,
    nombre_ciudad,
    direccion,
    estado_empresa,
    info_adicional
FROM
    empesas_solicitantes
order by nombre_empresa
;
--------------------------------------------------------
--  DDL for View LIBRODEOBRA_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "LIBRODEOBRA_VIEW" ("PROYECTO_ID", "NOMBRE_PROYECTO", "MONTO", "LIBRO_OBRA_ID", "FECHA_CREACION", "FECHA_FIN_PROYECTO", "RESPONSABLE_ID", "TIPO_PROYECTO_ID", "CONTRATO_ID", "ANTICIPO_VALOR", "FECHA_CONTRATO", "FECHA_FIN", "TIEMPO_MESES", "CONTRATISTA", "ADMINISTRADOR", "FISCALIZADOR", "OBSERVACIONES_ADMINISTRADOR", "OBSERVACIONES_CONTRATISTA", "OBSERVACIONES_FISCALIZADOR") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    proyecto_id,
    nombre_proyecto,
    monto,
    libro_de_obra.libro_obra_id,
    fecha_creacion,
    --fecha_inicio,
    fecha_fin as fecha_fin_proyecto,
    responsable_id,
    tipo_proyecto.tipo_proyecto_id,
    tipo_proyecto.nombre_tipo_proyecto
    contrato_id,
    anticipo_valor,
    fecha_contrato,
    fecha_fin,
    tiempo_meses,
    --comentario,
    cont.apellidos||' '||cont.nombres as Contratista,
    adm.apellidos||' '||adm.nombres as Administrador,
    fis.apellidos||' '||fis.nombres as Fiscalizador,
    libro_de_obra.observaciones_administrador,
    libro_de_obra.observaciones_contratista,
    libro_de_obra.observaciones_fiscalizador
FROM
    proyecto  natural join contrato 
inner join personal_obra cont on cont.PERSONAL_ID=CONTRATISTA_ID
inner join personal_obra adm on adm.PERSONAL_ID=ADMINISTRADOR_ID
inner join personal_obra fis on fis.PERSONAL_ID=FISCALIZADOR_ID
inner join TIPO_PROYECTO on tipo_proyecto.tipo_proyecto_id=proyecto.tipo_proyecto_id
inner JOIN LIBRO_DE_OBRA on libro_de_obra.contrato_id=contrato.contrato_id
ORDER BY fecha_contrato desc
;
--------------------------------------------------------
--  DDL for View LISTADO_GESTION_PRECONTRACTUAL_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "LISTADO_GESTION_PRECONTRACTUAL_VIEW" ("ID", "PROYECTO", "MONTO", "FECHA_INICIO", "FECHA_FIN", "PLAZO", "OBSERVACIONES", "TIPO", "ESTADO_ID", "NOMBRE_ESTADOS", "NOMBRE_SECTOR", "SECTOR_ID", "NOMBRE_TIPO_PROYECTO", "TIPO_PROYECTO_ID", "DEPENDENCIA") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    oferta_id as id,
    --solicitud_proyecto_id,
    titulo_proyecto as proyecto,
    monto_presupuestado as monto,
    fecha_inicio as fecha_inicio,
    fecha_fin as fecha_fin,
    plazo_de_ejecucion_propuesto as plazo,
    to_clob(observaciones) as observaciones,
    'OFERTA' AS TIPO,
    estados_configurados.estado_id,
    estados_configurados.nombre_estados,
    SECTOR.NOMBRE_SECTOR,
    SECTOR.SECTOR_ID,
    TIPO_PROYECTO.NOMBRE_TIPO_PROYECTO,
    TIPO_PROYECTO.TIPO_PROYECTO_ID,
    OFERTA.SOLICITUD_PROYECTO_ID AS DEPENDENCIA
FROM
    oferta
    LEFT JOIN estados_configurados on estados_configurados.estado_id=oferta.estado_id
    LEFT JOIN SOLICITUD_PROYECTO on(SOLICITUD_PROYECTO.SOLICITUD_PROYECTO_ID=oferta.solicitud_proyecto_id)
    LEFT JOIN SECTOR on(SECTOR.SECTOR_ID=SOLICITUD_PROYECTO.SECTOR_ID)
    LEFT JOIN TIPO_PROYECTO on(TIPO_PROYECTO.TIPO_PROYECTO_ID=SOLICITUD_PROYECTO.TIPO_PROYECTO_ID)
UNION ALL
SELECT
    solicitud_proyecto_id as id,
    nombre_proyecto as proyecto,
    to_number(monto) as monto,
    --fecha_creacion,
    to_date(fecha_inicio_ejecucion) as fecha_inicio,
    to_date(fecha_fin_ejecucion)as fecha_fin,
    (to_number(to_char(fecha_inicio_ejecucion,'YYYY'))-to_number(to_char(fecha_fin_ejecucion,'YYYY')))as plazo,--responsable_id,
     justificacion_tecnica as observaciones,
    'SOLICITUD'AS TIPO,
    estados_configurados.estado_id,
    estados_configurados.nombre_estados,
    SECTOR.NOMBRE_SECTOR,
    SECTOR.SECTOR_ID,
    TIPO_PROYECTO.NOMBRE_TIPO_PROYECTO,
    TIPO_PROYECTO.TIPO_PROYECTO_ID,
    0 AS DEPENDENCIA
    /*fecha_limite_postulacion,
    descripcion_solicitud,
    estado_solicitud_id,
    justificacion_tecnica,
    parroquia_id,
    ciudad,
    empresa_id*/
FROM
    solicitud_proyecto
    LEFT JOIN estados_configurados on estados_configurados.estado_id=solicitud_proyecto.estado_solicitud_id
    LEFT JOIN SECTOR on(SECTOR.SECTOR_ID=SOLICITUD_PROYECTO.SECTOR_ID)
    LEFT JOIN TIPO_PROYECTO on(TIPO_PROYECTO.TIPO_PROYECTO_ID=SOLICITUD_PROYECTO.TIPO_PROYECTO_ID)
WHERE solicitud_proyecto_id not in(select solicitud_proyecto_id from OFERTA)
;
--------------------------------------------------------
--  DDL for View LOCALIDADES_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "LOCALIDADES_VIEW" ("ID_PARROQUIA", "NOMBRE_PARROQUIA", "ID_CANTON", "NOMBRE_CANTON", "NOMBRE_PROVINCIA", "ID_PROVINCIA", "ID_PAIS", "NOMBRE_PAIS") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    parroquia.id_parroquia,
    parroquia.nombre_parroquia,
    parroquia.id_canton,
    gproy_elel.canton.nombre_canton,
    gproy_elel.provincia.nombre_provincia,
    gproy_elel.canton.id_provincia,
    gproy_elel.pais.id_pais,
    gproy_elel.pais.nombre_pais
FROM
         parroquia
    INNER JOIN gproy_elel.canton ON parroquia.id_canton = gproy_elel.canton.id_canton
    INNER JOIN gproy_elel.provincia ON gproy_elel.canton.id_provincia = gproy_elel.provincia.id_provincia
    INNER JOIN gproy_elel.pais ON gproy_elel.provincia.id_pais = gproy_elel.pais.id_pais
ORDER BY
    parroquia.nombre_parroquia,
    gproy_elel.canton.nombre_canton,
    gproy_elel.provincia.nombre_provincia
;
--------------------------------------------------------
--  DDL for View NOTIFICACIONES_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "NOTIFICACIONES_VIEW" ("NOTIFICA_ID", "SOLICITUD_PROYECTO_ID", "PROYECTO_ID", "MENSAJE", "FECHA_REGISTRO", "ORIGEN_USUARIO_ID", "DESTINO_USUARI", "ATENDIDO_SN", "FECHA_ATENCION", "USUARIO_ID", "GENERADOPOR", "DESTINATARIO", "SOLICITUD_PROYECTO", "NOMBRE_PROYECTO1", "OFERTA_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    notificaciones.notifica_id,
    notificaciones.solicitud_proyecto_id,
    notificaciones.proyecto_id,
    notificaciones.mensaje,
    notificaciones.fecha_registro,
    notificaciones.origen_usuario_id,
    notificaciones.destino_usuari,
    notificaciones.atendido_sn,
    notificaciones.fecha_atencion,
    gproy_elel.secur_usuarios_app.usuario_id,
    gproy_elel.secur_usuarios_app.nombreusuario AS generadopor,
    secur_usuarios_app1.nombreusuario           AS destinatario,
    gproy_elel.solicitud_proyecto.nombre_proyecto AS Solicitud_Proyecto,
    gproy_elel.proyecto.nombre_proyecto         AS nombre_proyecto1,
    gproy_elel.oferta.oferta_id
FROM
         notificaciones
    LEFT JOIN gproy_elel.secur_usuarios_app ON notificaciones.origen_usuario_id = gproy_elel.secur_usuarios_app.usuario_id
    LEFT JOIN gproy_elel.secur_usuarios_app secur_usuarios_app1 ON notificaciones.destino_usuari = secur_usuarios_app1.usuario_id
    LEFT JOIN gproy_elel.solicitud_proyecto ON notificaciones.solicitud_proyecto_id = gproy_elel.solicitud_proyecto.solicitud_proyecto_id
    LEFT JOIN gproy_elel.oferta ON oferta.oferta_id=notificaciones.oferta_id
    LEFT JOIN gproy_elel.proyecto ON notificaciones.proyecto_id = gproy_elel.proyecto.proyecto_id
ORDER BY notificaciones.fecha_registro DESC
;
--------------------------------------------------------
--  DDL for View PLANILLA_GENERADA_DETL_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PLANILLA_GENERADA_DETL_VIEW" ("LIBRO_OBRA_ID", "CONTRATO_ID", "OBSERVACIONES_ADMINISTRADOR", "OBSERVACIONES_FISCALIZADOR", "OBSERVACIONES_CONTRATISTA", "NRO_PLANILLA", "ACTIVIDAD_ID", "DESCRIPCION", "FECHA_CRAR_PLANILLA", "PLANILLA_ID", "LIBRO_OBRA_ACTIVIDADES_REALIZADAS_ACTIVIDAD_ID", "ACTIVIDAD_REALIZADA", "RUBRO", "CANTIDAD", "CEJEC_ACUMULADAS", "CEJEC_ANTERIORES", "CEJEC_ESTEPERIODO", "DETALLE_PLANILLAID", "PORC_AVANCE_ACUMULADO", "PRECIO_TOTAL", "PRECIO_UNITARIO", "UNIDAD", "VALEJEC_ACUMULADAS", "VALEJEC_ACUMULADAS1", "VALEJEC_ANTERIORES") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  select lobr.libro_obra_id,
       lobr.contrato_id,
       lobr.observaciones_administrador,
       lobr.observaciones_fiscalizador,
       lobr.observaciones_contratista,
       plg.nro_planilla,
       avob.actividad_id,
       avob.descripcion,
       avob.fecha_crar_planilla,
       avob.planilla_id,
       avob.libro_obra_actividades_realizadas_actividad_id,
       lobar.actividad_realizada,
       avob.rubro,
       dtlpac.cantidad,
       dtlpac.cejec_acumuladas,
       dtlpac.cejec_anteriores,
       --dtlpac.cejec_anteriores,
       dtlpac.cejec_esteperiodo,
       dtlpac.detalle_planillaid,
       dtlpac.porc_avance_acumulado,
       dtlpac.precio_total,
       dtlpac.precio_unitario,
       dtlpac.unidad,
       dtlpac.valejec_acumuladas,
       dtlpac.valejec_acumuladas1,
       dtlpac.valejec_anteriores
from libro_de_obra lobr inner join planilla_generada plg
inner join anexo_volumen_de_obra avob on avob.planilla_id=plg.planilla_id
on lobr.libro_obra_id=plg.libro_obra_id
inner JOIN libro_obra_actividades_realizadas lobar
on lobar.actividad_id=avob.actividad_id
inner join detalle_planilla_contractual dtlpac
on dtlpac.anexo_volumenobra_id=avob.anexo_volumenobra_id
;
