  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PLANILLA_GENERADA_VIEW" ("LIBRO_OBRA_ID", "CONTRATO_ID", "OBSERVACIONES_ADMINISTRADOR", "OBSERVACIONES_FISCALIZADOR", "OBSERVACIONES_CONTRATISTA", "NRO_PLANILLA") DEFAULT COLLATION "USING_NLS_COMP"  AS 
