;
--------------------------------------------------------
--  DDL for View PLANILLAS_GENERADAS_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PLANILLAS_GENERADAS_VIEW" ("NOMBRE_PROYECTO", "MONTO", "PROYECTO_ID", "FECHA_INICIO_EJECUCION", "FECHA_FIN_EJECUCION", "CONTRATO_ID", "ANTICIPO_VALOR", "FECHA_CONTRATO", "FECHA_FIN_CONTRATO", "TIEMPO_MESES", "NRO_PLANILLA", "FECHA_CREAR_PLANILLA", "MONTO_TOTAL", "FECHA_INICIO", "FECHA_FIN_PLANILLA", "ESTADO_ID", "NOMBRE_ESTADOS", "NOMBRE_TIPO_PROYECTO", "TIPO_PROYECTO_ID", "NOMBRE_SECTOR", "SECTOR_ID", "TIPO_ESTADO", "CONTRATISTA_ID", "APELLIDOS_CONTRATISTA", "NOMBRES_CONTRATISTA", "ADMINISTRADOR_ID", "PERSONAL_ID", "APELLIDOS_ADMIN", "NOMBRES_ADMIN", "FISCALIZADOR_ID", "APELLIDOS_FISCAL", "NOMBRES_FISCAL", "NRO_CEDULA_CONTRATISTA", "NRO_CEDULA_ADMIN", "NRO_CEDULA_FISCAL", "PLANILLA_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  select PROYECTO.NOMBRE_PROYECTO as NOMBRE_PROYECTO,
    PROYECTO.MONTO as MONTO,
    PROYECTO.PROYECTO_ID as PROYECTO_ID,
    PROYECTO.FECHA_INICIO_EJECUCION as FECHA_INICIO_EJECUCION,
    PROYECTO.FECHA_FIN_EJECUCION as FECHA_FIN_EJECUCION,
    CONTRATO.CONTRATO_ID as CONTRATO_ID,
    CONTRATO.ANTICIPO_VALOR as ANTICIPO_VALOR,
    CONTRATO.FECHA_CONTRATO as FECHA_CONTRATO,
    CONTRATO.FECHA_FIN as FECHA_FIN_contrato,
    CONTRATO.TIEMPO_MESES as TIEMPO_MESES,
    PLANILLA_CONTRACTUAL.NRO_PLANILLA as NRO_PLANILLA,
    PLANILLA_CONTRACTUAL.FECHA_CREAR_PLANILLA as FECHA_CREAR_PLANILLA,
    PLANILLA_CONTRACTUAL.MONTO_TOTAL as MONTO_TOTAL,
    PLANILLA_CONTRACTUAL.FECHA_INICIO as FECHA_INICIO,
    PLANILLA_CONTRACTUAL.FECHA_FIN as FECHA_FIN_Planilla,
    ESTADOS_CONFIGURADOS.ESTADO_ID as ESTADO_ID,
    ESTADOS_CONFIGURADOS.NOMBRE_ESTADOS as NOMBRE_ESTADOS,
    TIPO_PROYECTO.NOMBRE_TIPO_PROYECTO as NOMBRE_TIPO_PROYECTO,
    TIPO_PROYECTO.TIPO_PROYECTO_ID as TIPO_PROYECTO_ID,
    SECTOR.NOMBRE_SECTOR as NOMBRE_SECTOR,
    SECTOR.SECTOR_ID as SECTOR_ID,
    ESTADOS_CONFIGURADOS.TIPO_ESTADO as TIPO_ESTADO,
    CONTRATO.CONTRATISTA_ID as CONTRATISTA_ID,
    PERSONAL_OBRA.APELLIDOS as APELLIDOS_CONTRATISTA,
    PERSONAL_OBRA.NOMBRES as NOMBRES_CONTRATISTA,
    CONTRATO.ADMINISTRADOR_ID as ADMINISTRADOR_ID,
    PERSONAL_OBRA_2.PERSONAL_ID as PERSONAL_ID,
    PERSONAL_OBRA_2.APELLIDOS as APELLIDOS_ADMIN,
    PERSONAL_OBRA_2.NOMBRES as NOMBRES_ADMIN,
    CONTRATO.FISCALIZADOR_ID as FISCALIZADOR_ID,
    PERSONAL_OBRA_3.APELLIDOS as APELLIDOS_FISCAL,
    PERSONAL_OBRA_3.NOMBRES as NOMBRES_FISCAL,
    PERSONAL_OBRA.NRO_CEDULA as NRO_CEDULA_CONTRATISTA,
    PERSONAL_OBRA_2.NRO_CEDULA as NRO_CEDULA_ADMIN,
    PERSONAL_OBRA_3.NRO_CEDULA as NRO_CEDULA_FISCAL,
    PLANILLA_CONTRACTUAL.PLANILLA_ID
 from PERSONAL_OBRA PERSONAL_OBRA_3,
    PERSONAL_OBRA PERSONAL_OBRA_2,
    PERSONAL_OBRA PERSONAL_OBRA,
    TIPO_PROYECTO TIPO_PROYECTO,
    SECTOR SECTOR,
    ESTADOS_CONFIGURADOS ESTADOS_CONFIGURADOS,
    CONTRATO CONTRATO,
    PLANILLA_CONTRACTUAL PLANILLA_CONTRACTUAL,
    OFERTA OFERTA,
    PROYECTO PROYECTO,
    SOLICITUD_PROYECTO SOLICITUD_PROYECTO 
 where OFERTA.SOLICITUD_PROYECTO_ID=SOLICITUD_PROYECTO.SOLICITUD_PROYECTO_ID
    and PROYECTO.OFERTA_ID=OFERTA.OFERTA_ID
    and CONTRATO.PROYECTO_ID=PROYECTO.PROYECTO_ID
    and PLANILLA_CONTRACTUAL.CONTRATO_ID=CONTRATO.CONTRATO_ID
    and PLANILLA_CONTRACTUAL.ESTADO_ID=ESTADOS_CONFIGURADOS.ESTADO_ID
    and SOLICITUD_PROYECTO.TIPO_PROYECTO_ID=TIPO_PROYECTO.TIPO_PROYECTO_ID
    and SOLICITUD_PROYECTO.SECTOR_ID=SECTOR.SECTOR_ID
    and CONTRATO.ADMINISTRADOR_ID=PERSONAL_OBRA.PERSONAL_ID
    and CONTRATO.CONTRATISTA_ID=PERSONAL_OBRA_2.PERSONAL_ID
    and CONTRATO.FISCALIZADOR_ID=PERSONAL_OBRA_3.PERSONAL_ID
;
--------------------------------------------------------
--  DDL for View PROYECTO_CONTRATO_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PROYECTO_CONTRATO_VIEW" ("PROYECTO_ID", "NOMBRE_PROYECTO", "MONTO", "FECHA_CREACION", "RESPONSABLE_ID", "TIPO_PROYECTO_ID", "NOMBRE_TIPO_PROYECTO", "CONTRATO_ID", "ANTICIPO_VALOR", "FECHA_CONTRATO", "FECHA_FIN", "TIEMPO_MESES", "OFERTA_ID", "CONTRATISTA", "ADMINISTRADOR", "FISCALIZADOR") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    proyecto_id,
    proyecto.nombre_proyecto,
    proyecto.monto,
    proyecto.fecha_creacion,
    --PROYECTO.fecha_inicio,
    --PROYECTO.fecha_fin as fecha_fin_proyecto,
    proyecto.responsable_id,
    tipo_proyecto.tipo_proyecto_id,
    tipo_proyecto.nombre_tipo_proyecto,
    contrato_id,
    anticipo_valor,
    contrato.fecha_contrato,
    contrato.fecha_fin,
    tiempo_meses,
    sp.oferta_id,
    --comentario,
    cont.apellidos||' '||cont.nombres as Contratista,
    adm.apellidos||' '||adm.nombres as Administrador,
    fis.apellidos||' '||fis.nombres as Fiscalizador
FROM
    proyecto  natural join contrato 
    inner join oferta SP ON sp.oferta_id=proyecto.oferta_id
    left join personal_obra cont on cont.PERSONAL_ID=CONTRATISTA_ID
    left join personal_obra adm on adm.PERSONAL_ID=ADMINISTRADOR_ID
    left join personal_obra fis on fis.PERSONAL_ID=FISCALIZADOR_ID
    INNER JOIN gproy_elel.solicitud_proyecto ON sp.solicitud_proyecto_id = gproy_elel.solicitud_proyecto.solicitud_proyecto_id
    inner join TIPO_PROYECTO on tipo_proyecto.tipo_proyecto_id=solicitud_proyecto.tipo_proyecto_id
ORDER BY fecha_contrato desc
;
--------------------------------------------------------
--  DDL for View PROYECTOS_POR_TIPO_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PROYECTOS_POR_TIPO_VIEW" ("TIPO_PROYECTO_ID", "TIPO_PROYECTO", "CANTIDAD_TERMINADOS", "CANTIDAD_POR_TERMINAR", "TOTAL_PROYECTOS") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT 
    tp.tipo_proyecto_id,
    NVL(tp.nombre_tipo_proyecto, 'Sin Clasificar') AS tipo_proyecto,
    
    -- 1. Proyectos Terminados
    COUNT(
        CASE 
            WHEN UPPER(e.nombre_estados) IN ('TERMINADO', 'FINALIZADO', 'COMPLETADO') 
              OR (p.fecha_fin_ejecucion IS NOT NULL AND p.fecha_fin_ejecucion <= SYSDATE)
            THEN 1 
        END
    ) AS cantidad_terminados,
    
    -- 2. Proyectos Por Terminar (En ejecución / Pendientes)
    COUNT(
        CASE 
            WHEN p.proyecto_id IS NOT NULL 
             AND (
                 UPPER(e.nombre_estados) NOT IN ('TERMINADO', 'FINALIZADO', 'COMPLETADO') 
                 OR e.nombre_estados IS NULL
             )
             AND (p.fecha_fin_ejecucion IS NULL OR p.fecha_fin_ejecucion > SYSDATE)
            THEN 1 
        END
    ) AS cantidad_por_terminar,
    
    -- Total general por tipo de proyecto
    COUNT(p.proyecto_id) AS total_proyectos

FROM tipo_proyecto tp
LEFT JOIN solicitud_proyecto sp ON tp.tipo_proyecto_id = sp.tipo_proyecto_id
LEFT JOIN oferta o              ON sp.solicitud_proyecto_id = o.solicitud_proyecto_id
LEFT JOIN proyecto p            ON o.oferta_id = p.oferta_id
LEFT JOIN estados_configurados e              ON p.estado_proyecto_id = e.estado_id
GROUP BY 
    tp.tipo_proyecto_id,
    tp.nombre_tipo_proyecto
ORDER BY 
    tipo_proyecto ASC
;
--------------------------------------------------------
--  DDL for View PROYECTOS_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PROYECTOS_VIEW" ("PROYECTO_ID", "NOMBRE_PROYECTO", "MONTO", "FECHA_INICIO_EJECUCION", "FECHA_FIN_EJECUCION", "CRONOGRAMA_ID", "FECHA_INICIO", "FECHA_FIN", "COMENTARIO", "OFERTA_ID", "SOLICITUD_PROYECTO_ID", "ESTADO_ID", "NOMBRE_ESTADOS", "SECTOR_ID", "NOMBRE_SECTOR", "TIPO_PROYECTO_ID", "NOMBRE_TIPO_PROYECTO", "EMPRESA_ID", "NOMBRE_EMPRESA", "RUC") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    gproy_elel.proyecto.proyecto_id,
    gproy_elel.proyecto.nombre_proyecto,
    gproy_elel.proyecto.monto,
    gproy_elel.proyecto.fecha_inicio_ejecucion,
    gproy_elel.proyecto.fecha_fin_ejecucion,
    gproy_elel.cronograma_actividades.cronograma_id,
    gproy_elel.cronograma_actividades.fecha_inicio,
    gproy_elel.cronograma_actividades.fecha_fin,
    gproy_elel.cronograma_actividades.comentario,
    gproy_elel.proyecto.oferta_id,
    gproy_elel.solicitud_proyecto.solicitud_proyecto_id,
    gproy_elel.estados_configurados.estado_id,
    gproy_elel.estados_configurados.nombre_estados,
    gproy_elel.sector.sector_id,
    gproy_elel.sector.nombre_sector,
    gproy_elel.tipo_proyecto.tipo_proyecto_id,
    gproy_elel.tipo_proyecto.nombre_tipo_proyecto,
    gproy_elel.empesas_solicitantes.empresa_id,
    gproy_elel.empesas_solicitantes.nombre_empresa,
    gproy_elel.empesas_solicitantes.ruc
FROM
         gproy_elel.cronograma_actividades
    INNER JOIN gproy_elel.proyecto ON gproy_elel.cronograma_actividades.proyecto_id = gproy_elel.proyecto.proyecto_id
    INNER JOIN gproy_elel.oferta ON gproy_elel.proyecto.oferta_id = gproy_elel.oferta.oferta_id
    INNER JOIN gproy_elel.solicitud_proyecto ON gproy_elel.oferta.solicitud_proyecto_id = gproy_elel.solicitud_proyecto.solicitud_proyecto_id
    INNER JOIN gproy_elel.estados_configurados ON gproy_elel.proyecto.estado_proyecto_id = gproy_elel.estados_configurados.estado_id
    INNER JOIN gproy_elel.sector ON gproy_elel.solicitud_proyecto.sector_id = gproy_elel.sector.sector_id
    INNER JOIN gproy_elel.tipo_proyecto ON gproy_elel.solicitud_proyecto.tipo_proyecto_id = gproy_elel.tipo_proyecto.tipo_proyecto_id
    INNER JOIN gproy_elel.empesas_solicitantes ON gproy_elel.solicitud_proyecto.empresa_id = gproy_elel.empesas_solicitantes.empresa_id
;
--------------------------------------------------------
--  DDL for View PROYECTO_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "PROYECTO_VIEW" ("PROYECTO_ID", "NOMBRE_PROYECTO", "MONTO", "FECHA_CREACION", "FECHA_INICIO_EJECUCION", "FECHA_FIN_EJECUCION", "ESTADO_PROYECTO_ID", "OFERTA_ID", "ANTICIPO_VALOR", "FECHA_DEPOSITO_ANTICIPO", "NRO_CTA_ORIGEN", "SALDO", "VALOR_RESTANTE", "ENTIDAD_BANCARIA_ANTICIPO_ID", "ENTIDAD_BANCARIA_VALREST_ID", "INFORMACION_ADICIONAL", "NOMBRE_ENTIDAD_FINANCIERA", "NOMBRE_SECTOR", "SECTOR_ID", "TIPO_PROYECTO_ID", "NOMBRE_TIPO_PROYECTO", "EMPRESA_ID", "NOMBRE_EMPRESA", "ESTADO_ID", "NOMBRE_ESTADOS") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT DISTINCT
    proyecto.proyecto_id,
    proyecto.nombre_proyecto,
    proyecto.monto,
    proyecto.fecha_creacion,
    proyecto.fecha_inicio_ejecucion,
    proyecto.fecha_fin_ejecucion,
    proyecto.estado_proyecto_id,
    proyecto.oferta_id,
    proyecto.anticipo_valor,
    proyecto.fecha_deposito_anticipo,
    proyecto.nro_cta_origen,
    proyecto.saldo,
    proyecto.valor_restante,
    proyecto.entidad_bancaria_anticipo_id,
    proyecto.entidad_bancaria_valrest_id,
    proyecto.informacion_adicional,
    gproy_elel.entidad_financiera.nombre_entidad_financiera,
    gproy_elel.sector.nombre_sector,
    gproy_elel.sector.sector_id,
    gproy_elel.tipo_proyecto.tipo_proyecto_id,
    gproy_elel.tipo_proyecto.nombre_tipo_proyecto,
    gproy_elel.empesas_solicitantes.empresa_id,
    gproy_elel.empesas_solicitantes.nombre_empresa,
    gproy_elel.estados_configurados.estado_id,
    gproy_elel.estados_configurados.nombre_estados
FROM
         proyecto
    LEFT JOIN gproy_elel.entidad_financiera ON proyecto.entidad_bancaria_anticipo_id = gproy_elel.entidad_financiera.etidad_financiera_id
                                                AND proyecto.entidad_bancaria_valrest_id = gproy_elel.entidad_financiera.etidad_financiera_id
    INNER JOIN gproy_elel.oferta ON proyecto.oferta_id = gproy_elel.oferta.oferta_id
    INNER JOIN gproy_elel.solicitud_proyecto ON gproy_elel.oferta.solicitud_proyecto_id = gproy_elel.solicitud_proyecto.solicitud_proyecto_id
    INNER JOIN gproy_elel.sector ON gproy_elel.solicitud_proyecto.sector_id = gproy_elel.sector.sector_id
    INNER JOIN gproy_elel.tipo_proyecto ON gproy_elel.solicitud_proyecto.tipo_proyecto_id = gproy_elel.tipo_proyecto.tipo_proyecto_id
    INNER JOIN gproy_elel.empesas_solicitantes ON gproy_elel.solicitud_proyecto.empresa_id = gproy_elel.empesas_solicitantes.empresa_id
    INNER JOIN gproy_elel.estados_configurados ON proyecto.estado_proyecto_id = gproy_elel.estados_configurados.estado_id
ORDER BY
    proyecto.fecha_inicio_ejecucion DESC
;
--------------------------------------------------------
--  DDL for View SECTORES_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SECTORES_VIEW" ("ESTADO_ID", "NOMBRE_ESTADOS") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    estado_id,
    nombre_estados
FROM
    estados_configurados
WHERE tipo_estado='SECTORES'
;
--------------------------------------------------------
--  DDL for View SOLICITUDES_OFERTAS__VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOLICITUDES_OFERTAS__VIEW" ("ESTADO_ID", "ESTADO", "TIPO_ESTADO", "TOTAL_SOLICITUDES", "TOTAL_OFERTAS", "TOTAL_ACUMULADO") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT 
    e.estado_id,
    NVL(e.nombre_estados, 'Sin Estado') AS estado,
    NVL(e.tipo_estado, 'General')       AS tipo_estado,
    
    -- Count condicional de Solicitudes vinculadas al Estado
    COUNT(DISTINCT sp.solicitud_proyecto_id) AS total_solicitudes,
    
    -- Count condicional de Ofertas vinculadas al Estado
    COUNT(DISTINCT o.oferta_id) AS total_ofertas,
    
    -- Total Consolidado por Estado
    (COUNT(DISTINCT sp.solicitud_proyecto_id) + COUNT(DISTINCT o.oferta_id)) AS total_acumulado

FROM estados_configurados e
LEFT JOIN solicitud_proyecto sp ON e.estado_id = sp.estado_solicitud_id
LEFT JOIN oferta o             ON e.estado_id = o.estado_id
GROUP BY 
    e.estado_id,
    e.nombre_estados,
    e.tipo_estado
HAVING 
    (COUNT(DISTINCT sp.solicitud_proyecto_id) + COUNT(DISTINCT o.oferta_id)) > 0
ORDER BY 
    total_acumulado DESC,
    estado ASC
;
--------------------------------------------------------
--  DDL for View SOLICTUDES_PROYECTOS_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "SOLICTUDES_PROYECTOS_VIEW" ("SOLICITUD_PROYECTO_ID", "NOMBRE_PROYECTO", "MONTO", "FECHA_CREACION", "FECHA_LIMITE_POSTULACION", "DESCRIPCION_SOLICITUD", "ESTADOSOLICITUD", "ESTADOSOLICITUD1", "JUSTIFICACION_TECNICA", "CIUDAD", "PARROQUIA_ID", "TIPO_PROYECTO_ID", "NOMBRE_TIPO_PROYECTO", "RESPONSABLE_ID", "SECTOR_ID", "SECTOR", "NOMBRE_PARROQUIA", "NOMBRE_EMPRESA", "EMPRESA_ID") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT
    gproy_elel.solicitud_proyecto.solicitud_proyecto_id,
    gproy_elel.solicitud_proyecto.nombre_proyecto,
    gproy_elel.solicitud_proyecto.monto,
    gproy_elel.solicitud_proyecto.fecha_creacion,
    gproy_elel.solicitud_proyecto.fecha_limite_postulacion,
    gproy_elel.solicitud_proyecto.descripcion_solicitud,
    estado_solicictud.nombre_estados EstadoSolicitud,
    estado_solicictud.estado_id EstadoSolicitud1,
    gproy_elel.solicitud_proyecto.justificacion_tecnica,
    gproy_elel.solicitud_proyecto.ciudad,
    gproy_elel.solicitud_proyecto.parroquia_id,
    gproy_elel.tipo_proyecto.tipo_proyecto_id,
    gproy_elel.tipo_proyecto.nombre_tipo_proyecto,
    gproy_elel.solicitud_proyecto.responsable_id,
    sectores.estado_id sector_id,
    sectores.nombre_estados AS Sector,
    parroquia.nombre_parroquia,
    empesas_solicitantes.nombre_empresa,
    empesas_solicitantes.empresa_id
FROM
         gproy_elel.solicitud_proyecto
    INNER JOIN gproy_elel.tipo_proyecto ON gproy_elel.solicitud_proyecto.tipo_proyecto_id = gproy_elel.tipo_proyecto.tipo_proyecto_id
    INNER JOIN gproy_elel.estados_configurados  estado_solicictud ON gproy_elel.solicitud_proyecto.estado_solicitud_id = estado_solicictud.estado_id
    INNER JOIN gproy_elel.estados_configurados  sectores on gproy_elel.solicitud_proyecto.sector_id= sectores.estado_id
    INNER JOIN parroquia on parroquia.id_parroquia=solicitud_proyecto.parroquia_id
    INNER JOIN empesas_solicitantes ON empesas_solicitantes.empresa_id=gproy_elel.solicitud_proyecto.empresa_id
;
--------------------------------------------------------
--  DDL for View TIPO_PROYECTO_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TIPO_PROYECTO_VIEW" ("TIPO_PROYECTO_ID", "NOMBRE_TIPO_PROYECTO") DEFAULT COLLATION "USING_NLS_COMP"  AS 
