--  DDL for View USUARIOS_ROLES_VIEW
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "USUARIOS_ROLES_VIEW" ("NOMBREUSUARIO", "USUARIO_ID", "NOMBREROL") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  select SECUR_USUARIOS_APP.NOMBREUSUARIO as NOMBREUSUARIO,
    SECUR_USUARIOS_APP.USUARIO_ID as USUARIO_ID,
    SECUR_ROLES.NOMBREROL as NOMBREROL 
 from SECUR_ROLES SECUR_ROLES,
    --SECUR_ROLES_USUARIOS SECUR_ROLES_USUARIOS,
    SECUR_USUARIOS_APP SECUR_USUARIOS_APP 
 where /*SECUR_ROLES_USUARIOS.USUARIO_ID=SECUR_USUARIOS_APP.USUARIO_ID
    and */SECUR_USUARIOS_APP.ROL_ID=SECUR_ROLES.ROL_ID
;
--------------------------------------------------------
--  DDL for View VW_SECUR_MENU_APEX
--------------------------------------------------------

  CREATE OR REPLACE FORCE EDITIONABLE VIEW "VW_SECUR_MENU_APEX" ("LVL", "LABEL", "TARGET", "IS_CURRENT_LIST_ENTRY", "IMAGE") DEFAULT COLLATION "USING_NLS_COMP"  AS 
  SELECT 
    LEVEL AS lvl,
    nombre_menu AS label,
    -- Formato declarativo nativo para las URL de páginas en APEX
    CASE 
        WHEN pagina IS NOT NULL THEN 'f?p=' || SYS_CONTEXT('APEX$SESSION', 'APP_ID') || ':' || pagina || ':' || SYS_CONTEXT('APEX$SESSION', 'APP_SESSION') || '::NO:::'
        ELSE NULL 
    END AS target,
    'NO' AS is_current_list_entry,
    icono AS image
FROM (
    -- Subconsulta única con DISTINCT para consolidar accesos si el usuario tiene múltiples roles
    SELECT DISTINCT
        m.menu_id,
        m.submenudeid,
        m.nombre_menu,
        m.icono,
        m.pagina,
        m.orden_prioridad
    FROM secur_menu m
    JOIN secur_menu_roles mr      ON m.menu_id = mr.menu_id
    JOIN secur_roles_usuarios ru  ON mr.rol_id = ru.rol_id
    JOIN secur_usuarios_app u     ON ru.usuario_id = u.usuario_id
    WHERE UPPER(u.nombreusuario) = UPPER(SYS_CONTEXT('APEX$SESSION', 'APP_USER'))
      AND u.activo_sn = 'S'
      AND ru.activo_sn = 'S'
      AND mr.activo_sn = 'S'
)
START WITH submenudeid IS NULL
CONNECT BY PRIOR menu_id = submenudeid
ORDER SIBLINGS BY orden_prioridad
;
