  CREATE OR REPLACE EDITIONABLE TRIGGER "AI_PROYECTO_TRG" 
AFTER INSERT ON PROYECTO 
FOR EACH ROW 
DECLARE
  var_contrato_id contrato.contrato_id%type;
  var_libro_obra_id libro_de_obra.libro_obra_id%type;
BEGIN
    --Flujo completo de procesamiento de Obra.
    PKG_GESTION_OBRAS.prc_procesar_flujo_obra(
         p_proyecto_id       =>:NEW.PROYECTO_ID,
         p_usuario_id        =>null,
         p_contratista_id    =>null,
         p_administrador_id  =>null,
         p_fiscalizador_id   =>null,
         p_comentario        =>'CREADO POR EL SISTEMA EN '||CURRENT_DATE,
         p_contrato_id_out   =>var_contrato_id,
         p_libro_obra_id_out =>var_libro_obra_id
     );
   
END;
/
