--------------------------------------------------------
--  DDL for Trigger TRG_PROYECTO_FLUJO_COMPUESTO
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "TRG_PROYECTO_FLUJO_COMPUESTO" 
FOR INSERT OR UPDATE OF ANTICIPO_VALOR ON PROYECTO
-- CORRECCIÓN: Se eliminó la cláusula WHEN global para evitar el error ORA-25000
COMPOUND TRIGGER

  -- Colección en memoria para almacenar los IDs de los proyectos que cumplen la condición
  TYPE t_proyectos_ids IS TABLE OF PROYECTO.PROYECTO_ID%TYPE INDEX BY PLS_INTEGER;
  v_lista_proyectos t_proyectos_ids;

  -- Fase 1: Se ejecuta por cada fila afectada
  AFTER EACH ROW IS
  BEGIN
    -- Trasladamos la lógica de negocio aquí usando variables de enlace estándar (:NEW y :OLD)
    IF (INSERTING AND :NEW.ANTICIPO_VALOR > 0) 
       OR 
       (UPDATING AND (:OLD.ANTICIPO_VALOR IS NOT NULL OR :NEW.ANTICIPO_VALOR <> :OLD.ANTICIPO_VALOR)) 
    THEN
      -- Solo guardamos en memoria los proyectos que realmente necesitan disparar el flujo
      v_lista_proyectos(:NEW.PROYECTO_ID) := :NEW.PROYECTO_ID;
    END IF;
  END AFTER EACH ROW;

  -- Fase 2: Se ejecuta una sola vez al terminar la sentencia SQL
  AFTER STATEMENT IS
    v_idx             PROYECTO.PROYECTO_ID%TYPE;
    v_contrato_id_out NUMBER;
    v_libro_id_out    NUMBER;
    v_usuario_sistema CONSTANT NUMBER := 1; 
  BEGIN
    v_idx := v_lista_proyectos.FIRST;

    WHILE v_idx IS NOT NULL LOOP
      BEGIN
        PKG_GESTION_OBRAS.PRC_PROCESAR_FLUJO_OBRA (
          p_proyecto_id       => v_lista_proyectos(v_idx),
          p_usuario_id        => v_usuario_sistema,
          p_comentario        => 'Flujo generado automáticamente por Trigger debido a registro/cambio en Anticipo.',
          p_contrato_id_out   => v_contrato_id_out,
          p_libro_obra_id_out => v_libro_id_out
        );
      EXCEPTION
        WHEN OTHERS THEN
          -- Evita que el fallo de un registro bloquee operaciones masivas ajenas
          DBMS_OUTPUT.PUT_LINE('Error procesando flujo automático para Proyecto ID ' || v_idx || ': ' || SQLERRM);
      END;

      v_idx := v_lista_proyectos.NEXT(v_idx);
    END LOOP;
  END AFTER STATEMENT;

END TRG_PROYECTO_FLUJO_COMPUESTO;
/
ALTER TRIGGER "TRG_PROYECTO_FLUJO_COMPUESTO" ENABLE;
