--------------------------------------------------------
--  DDL for Trigger AU_SOLICITUD_PROYECTO_TRG
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "AU_SOLICITUD_PROYECTO_TRG" 
AFTER UPDATE OF ESTADO_SOLICITUD_ID ON SOLICITUD_PROYECTO 
for each row
DECLARE
   EX_CON_CONTRATO_ASIGNADO EXCEPTION;
BEGIN
 if  SOLICITUD_PROYECTO_TAPI.proyecto_tiene_contrato(:new.SOLICITUD_PROYECTO_ID)=0 then
  if :new.ESTADO_SOLICITUD_ID=2 then --2	Oferta Aprobada por el Solicitante
     PROYECTO_tapi.ins (
         p_DESCRIPCION_SOLICITUD =>:new.DESCRIPCION_SOLICITUD
        ,p_FECHA_CREACION =>sysdate
        ,p_MONTO =>:new.MONTO
        ,p_JUSTIFICACION_TECNICA =>:new.JUSTIFICACION_TECNICA 
        ,p_FECHA_INICIO_EJECUCION =>:new.FECHA_INICIO_EJECUCION
        ,p_RESPONSABLE_ID =>:new.RESPONSABLE_ID
        ,p_PARROQUIA_ID =>:new.PARROQUIA_ID
        ,p_FECHA_FIN_EJECUCION =>:new.FECHA_FIN_EJECUCION
        ,p_SECTOR_ID =>:new.SECTOR_ID
        ,p_TIPO_PROYECTO_ID =>:new.TIPO_PROYECTO_ID
        ,p_SOLICITUD_PROYECTO_ID =>:new.SOLICITUD_PROYECTO_ID
        ,p_ESTADO_PROYECTO_ID =>1--ACEPTADO
        ,p_CIUDAD =>:NEW.CIUDAD
        ,p_PROYECTO_ID =>NULL
        ,p_NOMBRE_PROYECTO =>:NEW.NOMBRE_PROYECTO
      );
  else
     RAISE EX_CON_CONTRATO_ASIGNADO;
  end if;
end if;
exception
  when EX_CON_CONTRATO_ASIGNADO then
     raise_application_error('-20101','El proyecto asociado a esta solicitud,'||
       ' no puede cambiar de estado porque ya tiene un CONTRATO asociado.');
END;
/
ALTER TRIGGER "AU_SOLICITUD_PROYECTO_TRG" DISABLE;
--------------------------------------------------------
--  DDL for Trigger AU_SOLICITUD_PROYECTO_COMP_TRG
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "AU_SOLICITUD_PROYECTO_COMP_TRG" 
FOR UPDATE OF ESTADO_SOLICITUD_ID ON SOLICITUD_PROYECTO
COMPOUND TRIGGER

  -- 1. Declaramos un tipo de registro y una colección para almacenar los datos de las filas afectadas
  TYPE t_solicitud_rec IS RECORD (
    solicitud_proyecto_id   SOLICITUD_PROYECTO.SOLICITUD_PROYECTO_ID%TYPE,
    estado_solicitud_id      SOLICITUD_PROYECTO.ESTADO_SOLICITUD_ID%TYPE,
    descripcion_solicitud    SOLICITUD_PROYECTO.DESCRIPCION_SOLICITUD%TYPE,
    monto                    SOLICITUD_PROYECTO.MONTO%TYPE,
    justificacion_tecnica    SOLICITUD_PROYECTO.JUSTIFICACION_TECNICA%TYPE,
    fecha_inicio_ejecucion   SOLICITUD_PROYECTO.FECHA_INICIO_EJECUCION%TYPE,
    responsable_id           SOLICITUD_PROYECTO.RESPONSABLE_ID%TYPE,
    parroquia_id             SOLICITUD_PROYECTO.PARROQUIA_ID%TYPE,
    fecha_fin_ejecucion      SOLICITUD_PROYECTO.FECHA_FIN_EJECUCION%TYPE,
    sector_id                SOLICITUD_PROYECTO.SECTOR_ID%TYPE,
    tipo_proyecto_id         SOLICITUD_PROYECTO.TIPO_PROYECTO_ID%TYPE,
    ciudad                   SOLICITUD_PROYECTO.CIUDAD%TYPE,
    nombre_proyecto          SOLICITUD_PROYECTO.NOMBRE_PROYECTO%TYPE
  );

  TYPE t_solicitud_list IS TABLE OF t_solicitud_rec;
  g_solicitudes t_solicitud_list := t_solicitud_list();

  -- Excepción personalizada
  EX_CON_CONTRATO_ASIGNADO EXCEPTION;
  PRAGMA EXCEPTION_INIT(EX_CON_CONTRATO_ASIGNADO, -20101);

  -- SECCIÓN 2: Se ejecuta una vez antes de que empiece el statement (Inicialización)
  BEFORE STATEMENT IS
  BEGIN
    g_solicitudes.DELETE; -- Limpiamos la colección en memoria
  END BEFORE STATEMENT;

  -- SECCIÓN 3: Se ejecuta POR CADA FILA (Aquí la tabla muta, NO hacemos SELECTs)
  AFTER EACH ROW IS
  BEGIN
    -- Solo almacenamos los valores en memoria, Oracle permite acceder a :NEW sin problemas
    g_solicitudes.EXTEND;
    g_solicitudes(g_solicitudes.LAST).solicitud_proyecto_id := :NEW.SOLICITUD_PROYECTO_ID;
    g_solicitudes(g_solicitudes.LAST).estado_solicitud_id    := :NEW.ESTADO_SOLICITUD_ID;
    g_solicitudes(g_solicitudes.LAST).descripcion_solicitud  := :NEW.DESCRIPCION_SOLICITUD;
    g_solicitudes(g_solicitudes.LAST).monto                  := :NEW.MONTO;
    g_solicitudes(g_solicitudes.LAST).justificacion_tecnica  := :NEW.JUSTIFICACION_TECNICA;
    g_solicitudes(g_solicitudes.LAST).fecha_inicio_ejecucion := :NEW.FECHA_INICIO_EJECUCION;
    g_solicitudes(g_solicitudes.LAST).responsable_id         := :NEW.RESPONSABLE_ID;
    g_solicitudes(g_solicitudes.LAST).parroquia_id           := :NEW.PARROQUIA_ID;
    g_solicitudes(g_solicitudes.LAST).fecha_fin_ejecucion    := :NEW.FECHA_FIN_EJECUCION;
    g_solicitudes(g_solicitudes.LAST).sector_id              := :NEW.SECTOR_ID;
    g_solicitudes(g_solicitudes.LAST).tipo_proyecto_id       := :NEW.TIPO_PROYECTO_ID;
    g_solicitudes(g_solicitudes.LAST).ciudad                 := :NEW.CIUDAD;
    g_solicitudes(g_solicitudes.LAST).nombre_proyecto        := :NEW.NOMBRE_PROYECTO;
  END AFTER EACH ROW;

  -- SECCIÓN 4: Se ejecuta AL FINAL del statement (La tabla YA NO MUTA, es seguro consultar)
  AFTER STATEMENT IS
  BEGIN
    IF g_solicitudes.COUNT > 0 THEN
      FOR i IN g_solicitudes.FIRST .. g_solicitudes.LAST LOOP

        -- Ahora sí podemos invocar al TAPI de forma segura
        IF SOLICITUD_PROYECTO_TAPI.proyecto_tiene_contrato(g_solicitudes(i).solicitud_proyecto_id) = 0 THEN

          IF g_solicitudes(i).estado_solicitud_id = 2 THEN 
            -- Ejecutamos la inserción mediante el TAPI de Proyecto
            PROYECTO_tapi.ins (
               p_descripcion_solicitud  => g_solicitudes(i).descripcion_solicitud
              ,p_fecha_creacion         => SYSDATE
              ,p_monto                  => g_solicitudes(i).monto
              ,p_justificacion_tecnica  => g_solicitudes(i).justificacion_tecnica 
              ,p_fecha_inicio_ejecucion => g_solicitudes(i).fecha_inicio_ejecucion
              ,p_responsable_id         => g_solicitudes(i).responsable_id
              ,p_parroquia_id           => g_solicitudes(i).parroquia_id
              ,p_fecha_fin_ejecucion    => g_solicitudes(i).fecha_fin_ejecucion
              ,p_sector_id              => g_solicitudes(i).sector_id
              ,p_tipo_proyecto_id       => g_solicitudes(i).tipo_proyecto_id
              ,p_solicitud_proyecto_id  => g_solicitudes(i).solicitud_proyecto_id
              ,p_estado_proyecto_id     => 1 -- ACEPTADO
              ,p_ciudad                 => g_solicitudes(i).ciudad
              ,p_proyecto_id            => NULL
              ,p_nombre_proyecto        => g_solicitudes(i).nombre_proyecto
            );
          ELSE
            RAISE EX_CON_CONTRATO_ASIGNADO;
          END IF;

        END IF;

      END LOOP;
    END IF;

  EXCEPTION
    WHEN EX_CON_CONTRATO_ASIGNADO THEN
       RAISE_APPLICATION_ERROR(-20101, 'El proyecto asociado a esta solicitud,'||
         ' no puede cambiar de estado porque ya tiene un CONTRATO asociado.');
  END AFTER STATEMENT;

END AU_SOLICITUD_PROYECTO_COMP_TRG;

/
