--  DDL for Trigger SOLICITUD_PROYECTO_TRG
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "SOLICITUD_PROYECTO_TRG" 
BEFORE INSERT ON SOLICITUD_PROYECTO 
FOR EACH ROW 
BEGIN
  <<COLUMN_SEQUENCES>>
  BEGIN
    IF INSERTING AND :NEW.SOLICITUD_PROYECTO_ID IS NULL THEN
      SELECT SOLICITUD_PROYECTO_SEQ.NEXTVAL INTO :NEW.SOLICITUD_PROYECTO_ID FROM SYS.DUAL;
    END IF;
  END COLUMN_SEQUENCES;
END;
