--------------------------------------------------------
--  DDL for Procedure ACTUALIZAR_CLAVE_USUARIO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "ACTUALIZAR_CLAVE_USUARIO" (
    p_usuario_id    IN SECUR_USUARIOS_APP.USUARIO_ID%TYPE,
    p_nombreusuario IN SECUR_USUARIOS_APP.NOMBREUSUARIO%TYPE,
    p_clave_plana   IN VARCHAR2
) 
IS
    v_hash_raw         RAW(64);
    v_clave_encriptada VARCHAR2(128); -- Ajustado a 128 por eficiencia
    v_retry_count      NUMBER := 0;
    v_max_retries      CONSTANT NUMBER := 3;
BEGIN
    -- 1. Generación de Hash fuera del bloque de actualización para reducir tiempo de bloqueo
    v_hash_raw := DBMS_CRYPTO.HASH(
        src => UTL_I18N.STRING_TO_RAW(UPPER(TRIM(p_nombreusuario)) || p_clave_plana, 'AL32UTF8'),
        typ => 4--+DBMS_CRYPTO.HASH_SH512
    );
    v_clave_encriptada := RAWTOHEX(v_hash_raw);

    -- 2. Implementación de reintento ante bloqueos (Deadlock handling)
    LOOP
        BEGIN
            UPDATE SECUR_USUARIOS_APP
            SET CLAVE = v_clave_encriptada
            WHERE USUARIO_ID = p_usuario_id;
            
            COMMIT;
            EXIT; -- Éxito, salir del bucle
            
        EXCEPTION
            WHEN OTHERS THEN
                -- ORA-00060 es el código de Deadlock típico
                IF SQLCODE IN (-60, -12860) AND v_retry_count < v_max_retries THEN
                    v_retry_count := v_retry_count + 1;
                    DBMS_SESSION.SLEEP(0.1); -- Pausa breve antes de reintentar
                ELSE
                    RAISE; -- Si no es bloqueo o excedimos reintentos, relanzar
                END IF;
        END;
    END LOOP;
END actualizar_clave_usuario;

/
