  CREATE OR REPLACE EDITIONABLE PACKAGE "PKG_GENERACION_PLANILLAS" AS

    -- Procedimiento anterior (carga masiva mensual)
    PROCEDURE PR_GENERAR_PLANILLA_MENSUAL (
        p_contrato_id IN NUMBER,
        p_fecha_mes   IN DATE
    );

    /**
     * Nuevo Procedimiento: Procesa una sola fila del Anexo de Volumen de Obra.
     * Si no existe la planilla para el contrato y mes/año de la fila, la crea.
     * Luego, inserta el detalle correspondiente.
     */
    PROCEDURE PR_PROCESAR_NUEVO_ANEXO (
        p_anexo_id         IN NUMBER,
        p_fecha_planilla   IN DATE,
        p_rubro            IN VARCHAR2,
        p_total            IN NUMBER,
        p_precio_unitario  IN NUMBER,
        p_actividad_id     IN NUMBER
    );
    --Nueva versión que acepta rango de fechas por Acrtibvidad al crear el Anexo.
    PROCEDURE PR_PROCESAR_NUEVO_ANEXO2 (
    p_anexo_id         IN NUMBER,
    p_fecha_inicio     IN DATE,
    p_fecha_fin        IN DATE,
    p_rubro            IN VARCHAR2,
    p_total            IN NUMBER,
    p_precio_unitario  IN NUMBER,
    p_actividad_id     IN NUMBER
);

END PKG_GENERACION_PLANILLAS;

/
--------------------------------------------------------
--  DDL for Package PKG_GESTION_CONTINGENCIAS
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE "PKG_GESTION_CONTINGENCIAS" AS

  /**
   * Abre un proceso de contingencia por un Acta de Recepción con Observaciones.
   * Modifica el estado del contrato a 'DISPUTA_TECNICA' o similar.
   */
  PROCEDURE PRC_REGISTRAR_CONTINGENCIA (
    p_contrato_id             IN NUMBER,
    p_descripcion_observacion IN VARCHAR2,
    p_dias_subsanacion        IN NUMBER,
    p_usuario_registra_id     IN NUMBER
  );

  /**
   * Cierra con éxito la contingencia si el Fiscalizador aprueba las correcciones.
   */
  PROCEDURE PRC_RESOLVER_CONTINGENCIA (
    p_contingencia_id     IN NUMBER,
    p_usuario_id          IN NUMBER
  );

  /**
   * Proceso por lotes (Ejecutable mediante Oracle Scheduler) que evalúa si los plazos
   * han expirado. Si expiraron, cambia el estado a INCUMPLIDA y ejecuta la 
   * Terminación Unilateral del Contrato.
   */
  PROCEDURE PRC_VERIFICAR_VENCIMIENTOS;

END PKG_GESTION_CONTINGENCIAS;

/
--------------------------------------------------------
--  DDL for Package PKG_GESTION_CONTINGENCIAS2
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE "PKG_GESTION_CONTINGENCIAS2" AS

  PROCEDURE PRC_REGISTRAR_CONTINGENCIA (
    p_contrato_id             IN NUMBER,
    p_descripcion_observacion IN VARCHAR2,
    p_dias_subsanacion        IN NUMBER,
    p_usuario_registra_id     IN NUMBER,
    p_planilla_id             IN NUMBER DEFAULT NULL -- Nuevo parámetro opcional
  );

  PROCEDURE PRC_RESOLVER_CONTINGENCIA (
    p_contingencia_id     IN NUMBER,
    p_usuario_id          IN NUMBER
  );

  PROCEDURE PRC_VERIFICAR_VENCIMIENTOS;

END PKG_GESTION_CONTINGENCIAS2;

/
--------------------------------------------------------
--  DDL for Package PKG_GESTION_OBRAS
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE "PKG_GESTION_OBRAS" AS

  /**
  * Orquesta todo el flujo de registro posterior a la creación de un Proyecto.
  * Realiza la inserción del Contrato, la apertura del Libro de Obra 
  * y la transferencia masiva de actividades del cronograma.
  */
  PROCEDURE PRC_TRANSFERIR_ACTIVIDADES (
    p_proyecto_id   IN NUMBER,
    p_libro_obra_id IN NUMBER
  );
  PROCEDURE PRC_PROCESAR_FLUJO_OBRA (
    p_proyecto_id       IN  NUMBER,
    p_usuario_id        IN  NUMBER,
    p_contratista_id    IN  NUMBER   DEFAULT NULL,
    p_administrador_id  IN  NUMBER   DEFAULT NULL,
    p_fiscalizador_id   IN  NUMBER   DEFAULT NULL,
    p_comentario        IN  VARCHAR2 DEFAULT NULL,
    p_contrato_id_out   OUT NUMBER,
    p_libro_obra_id_out OUT NUMBER
  );

END PKG_GESTION_OBRAS;

/
--------------------------------------------------------
--  DDL for Package PKG_LIQUIDACION_OBRA
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE "PKG_LIQUIDACION_OBRA" AS

  -- Estados lógicos de las planillas (Columna PLANILLA_CONTRACTUAL.ESTADO_ID)
  CN_ESTADO_BORRADOR  CONSTANT NUMBER := 64; -- En preparación
  CN_ESTADO_REVISION  CONSTANT NUMBER := 62; -- Enviada a Fiscalización
  CN_ESTADO_APROBADA  CONSTANT NUMBER := 61; -- Validada y aprobada para pago
  CN_ESTADO_DEVUELTA  CONSTANT NUMBER := 63; -- Devuelta con observaciones
  /*61	Planilla APROBADA
    62	Planilla REVISION
    63	Planilla DEVUELTA
    64	Planilla BORRADOR*/
  /**
   * Cambia el estado de una planilla a 'Revisión'.
   * Controla que la sumatoria acumulada de planillas no rompa el monto total del proyecto.
   */
  PROCEDURE PRC_PRESENTAR_PLANILLA (
    p_planilla_id    IN NUMBER,
    p_usuario_id     IN NUMBER
  );

  /**
   * Registra la aprobación o devolución definitiva por parte del Fiscalizador.
   * Actualiza las firmas de auditoría en el contrato maestro.
   */
  PROCEDURE PRC_EVALUAR_PLANILLA (
    p_planilla_id     IN NUMBER,
    p_fiscalizador_id IN NUMBER,
    p_nuevo_estado_id IN NUMBER,
    p_comentario      IN VARCHAR2
  );

END PKG_LIQUIDACION_OBRA;

