--Anexar o transferir desde Anexo de Volumen de Obra a la Planilla Detallada.
procedure transferir_para_detalle_planilla(p_ANEXO_VOLUMENOBRA_ID ANEXO_VOLUMEN_DE_OBRA.ANEXO_VOLUMENOBRA_ID%type,
                                           p_LIBRO_OBRA_ACTIVIDADES_REALIZADAS_ACTIVIDAD_ID ANEXO_VOLUMEN_DE_OBRA.LIBRO_OBRA_ACTIVIDADES_REALIZADAS_ACTIVIDAD_ID%Type,
                                           p_total ANEXO_VOLUMEN_DE_OBRA.TOTAL%Type,
                                           p_precio_unitario PLANILLA_CONTRACTUAL_DETALLE.PRECIO_UNITARIO%Type,
                                           --p_libro_obra_id libro_de_obra.LIBRO_OBRA_ID%TYPE,
                                           p_contrato_id in CONTRATO.CONTRATO_ID%type)
as

  P_VALEJEC_ANTERIORES FLOAT;
  P_VALEJEC_ACUMULADAS FLOAT;
  P_UNIDAD VARCHAR2(4);
  P_PORC_AVANCE_ACUMULADO FLOAT;
  P_VALEJEC_ACUMULADAS1 FLOAT;
  P_RUBRO NUMBER;
  P_PRECIO_TOTAL FLOAT;
  P_CEJEC_ESTEPERIODO FLOAT;
  P_CEJEC_ACUMULADAS FLOAT;
  P_CANTIDAD FLOAT;
  P_CEJEC_ANTERIORES FLOAT;
  P_PLANILLA_ID_out NUMBER;
  --P_PRECIO_UNITARIO FLOAT;
  P_PLANILLA_CREADA INTEGER:=0;
BEGIN
  --P_ANEXO_VOLUMENOBRA_ID := NULL;
  P_VALEJEC_ANTERIORES := NULL;
  P_VALEJEC_ACUMULADAS := NULL;
  P_UNIDAD := NULL;
  P_PORC_AVANCE_ACUMULADO := NULL;
  P_VALEJEC_ACUMULADAS1 := NULL;
  P_RUBRO := NULL;
  P_PRECIO_TOTAL := NULL;
  P_CEJEC_ESTEPERIODO := NULL;
  P_CEJEC_ACUMULADAS := NULL;
  P_CANTIDAD := NULL;
  P_CEJEC_ANTERIORES := 0;
  p_planilla_id_out := NULL;
  --P_PRECIO_UNITARIO := NULL;

 --Averigua si hay planilla creada para el Contrato.
 select count(1)into p_planilla_creada
 from planilla_contractual
 where planilla_contractual.contrato_id=p_contrato_id;

 if p_planilla_creada=0 then
   PLANILLA_CONTRACTUAL_TAPI.ins(
         p_FECHA_CREAR_PLANILLA => sysdate
        ,p_NRO_PLANILLA =>contrato_numero_seq.nextval
        ,p_CONTRATO_ID => p_contrato_id
        ,p_PLANILLA_ID => p_planilla_id_out);
        
    
 else
     --Inserta el detalle si hay planilla creada para el Contrato.
     PLANILLA_CONTRACTUAL_DETALLE_TAPI.ins (  P_ANEXO_VOLUMENOBRA_ID => P_ANEXO_VOLUMENOBRA_ID,
                                           P_VALEJEC_ANTERIORES => p_cejec_anteriores*p_precio_unitario,--Viene de ANTERIORES [10] = [5] * [7]
                                           P_VALEJEC_ACUMULADAS => P_VALEJEC_ACUMULADAS,
                                           P_UNIDAD => p_total,
                                           P_PORC_AVANCE_ACUMULADO => P_PORC_AVANCE_ACUMULADO,
                                           P_VALEJEC_ACUMULADAS1 => p_cejec_anteriores*p_precio_unitario+p_precio_unitario*P_CEJEC_ANTERIORES,--Viene de [12]=10+11
                                           P_RUBRO => P_RUBRO,
                                           P_PRECIO_TOTAL => p_precio_unitario*p_total,--Viene de [6] = [4] * [5]
                                           P_CEJEC_ESTEPERIODO => p_total,
                                           P_CEJEC_ACUMULADAS => p_total+P_CEJEC_ANTERIORES,--Viene de ACUMULADAS[9] = [7] + [8]
                                           P_CANTIDAD => P_CANTIDAD,
                                           P_CEJEC_ANTERIORES => P_CEJEC_ANTERIORES,
                                           P_PLANILLA_ID => p_planilla_id_out,
                                           P_PRECIO_UNITARIO => P_PRECIO_UNITARIO) ;  
 end if;
end;
end ANEXO_VOLUMEN_DE_OBRA_tapi;

