--Recuperar Actividad Individual.
procedure recuperar_actividad_id(p_proyecto_id in integer,
                                 p_libro_id in integer,
                                 p_actividaD_id in integer,
                                 p_cronograma_id out cronograma_actividades.cronograma_id%type,
                                 p_cronograma_actividad_dtl_id out cronograma_actividades.fecha_inicio%type,
                                 p_descripcion out varchar2,
                                 p_hora_inicio out CRONOGRA_ACTIVIDADES_DETALLES.hora_inicio%type,
                                 p_hora_fin out CRONOGRA_ACTIVIDADES_DETALLES.hora_fin%type)
                                 as
 begin
 /*SELECT 
      cro.cronograma_id,
      cro.fecha_inicio,
      cro.fecha_fin,-- Asumiendo una secuencia para la PK del detalle del libro
      :p_libro_obra_id,
      CAST(act.DESCRIPCION AS VARCHAR2(6000)), -- Conversión segura de CLOB a VARCHAR2 según tu destino
      'NO ESPECIFICADO',                       -- Campo obligatorio o por defecto en destino
      act.ACTIVIDAD_ID,
      act.hora_inicio,
      act.hora_fin,
      --act.cronograma_id 
      act.actividad_id
    FROM cronograma_actividades cro
    JOIN CRONOGRA_ACTIVIDADES_DETALLES act ON act.CRONOGRAMA_ID = cro.CRONOGRAMA_ID
    JOIN LIBRO_OBRA_ACTIVIDADES_REALIZADAS dest ON dest.actividad_id_cronograma=act.actividad_id
    WHERE cro.PROYECTO_ID = :p_proyecto_id AND dest.actividad_id=:P_ACTIVIDAD_CRONO_ID;*/
    null;
  exception
    when NO_DATA_FOUND then 
      p_cronograma_id:=NULL;
      p_cronograma_actividad_dtl_id :=NULL;
      p_descripcion:=NULL;
      p_hora_inicio:=NULL;
      p_hora_fin:=NULL;
 end;
end LIBRO_OBRA_ACTIVIDADES_REALIZADAS_tapi;

