  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "OFERTA_TAPI" 
is
-- insert
procedure ins (
--p_OFERTA_ID in OFERTA.OFERTA_ID%type
p_SOLICITUD_PROYECTO_ID in OFERTA.SOLICITUD_PROYECTO_ID%type
,p_TITULO_PROYECTO in OFERTA.TITULO_PROYECTO%type
