,p_ESTADO_SOLICITUD_ID_NUEVO out SOLICITUD_PROYECTO.ESTADO_SOLICITUD_ID%type
--,p_EMPRESA_ID in SOLICITUD_PROYECTO.EMPRESA_ID%type default null 
)
