--El proyecto tiene Contrato?
function solicitud_tiene_oferta(p_solici_proyecto_id PROYECTO.PROYECTO_ID%TYPE)RETURN INT
as
  var_contar_filas INT;
begin
   select count(solicitud_proyecto.solicitud_proyecto_id)
     into var_contar_filas
    from solicitud_proyecto inner join oferta on(oferta.solicitud_proyecto_id=solicitud_proyecto.solicitud_proyecto_id)
    where solicitud_proyecto.solicitud_proyecto_id=p_solici_proyecto_id;
    
    return var_contar_filas;
exception
  when NO_DATA_FOUND then
     return 0;
end;
--Crear Oferta
procedure crearOferta(p_solicitud_id Solicitud_Proyecto.SOLICITUD_PROYECTO_ID%type)
AS
 VAR_SOLICITUD_PROYECTO_REC SOLICITUD_PROYECTO_TAPI2;

begin
 SELECT
    solicitud_proyecto_id,
    nombre_proyecto,
    estado_solicitud_id,
    monto,
    justificacion_tecnica,
    fecha_creacion,
    fecha_inicio_ejecucion, 
    FECHA_FIN_EJECUCION
  
    
  INTO VAR_SOLICITUD_PROYECTO_REC
  FROM SOLICITUD_PROYECTO
  WHERE SOLICITUD_PROYECTO.SOLICITUD_PROYECTO_ID=p_solicitud_id ;
  
  OFERTA_TAPI.ins(
     p_SOLICITUD_PROYECTO_ID=>VAR_SOLICITUD_PROYECTO_REC.SOLICITUD_PROYECTO_ID
    ,p_TITULO_PROYECTO=>VAR_SOLICITUD_PROYECTO_REC.NOMBRE_PROYECTO
    ,p_ESTADO_ID =>VAR_SOLICITUD_PROYECTO_REC.ESTADO_SOLICITUD_ID
    ,p_MONTO_PRESUPUESTADO =>VAR_SOLICITUD_PROYECTO_REC.MONTO
    ,p_OBSERVACIONES =>VAR_SOLICITUD_PROYECTO_REC.JUSTIFICACION_TECNICA
    ,p_PLAZO_DE_EJECUCION_PROPUESTO =>(to_number(to_char(VAR_SOLICITUD_PROYECTO_REC.fecha_inicio_ejecucion,'YYYY'))-to_number(to_char(VAR_SOLICITUD_PROYECTO_REC.fecha_inicio_ejecucion,'YYYY')))
    ,p_FECHA_INICIO =>VAR_SOLICITUD_PROYECTO_REC.fecha_inicio_ejecucion
    ,p_FECHA_FIN=>VAR_SOLICITUD_PROYECTO_REC.fecha_inicio_ejecucion);
end;
end SOLICITUD_PROYECTO_tapi;

/
--------------------------------------------------------
--  DDL for Function AUTENTICAR_USUARIO_APEX
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "AUTENTICAR_USUARIO_APEX" (
    p_username IN VARCHAR2,
    p_password IN VARCHAR2
) RETURN BOOLEAN 
AUTHID DEFINER
IS
    v_hash_gen  VARCHAR2(128);
    v_hash_db   VARCHAR2(128);
    v_user_clean VARCHAR2(60) := UPPER(TRIM(p_username));
BEGIN
    -- Cálculo del hash
    v_hash_gen := RAWTOHEX(DBMS_CRYPTO.HASH(UTL_I18N.STRING_TO_RAW(v_user_clean || p_password, 'AL32UTF8'), 4));

    -- Búsqueda
    SELECT CLAVE INTO v_hash_db
    FROM GPROY_ELEL.SECUR_USUARIOS_APP
    WHERE UPPER(TRIM(NOMBREUSUARIO)) = v_user_clean
      AND ACTIVO_SN = 'S';

    -- Comparación y Log
    IF v_hash_gen = v_hash_db THEN
        INSERT INTO GPROY_ELEL.LOG_AUTENTICACION_DEBUG (usuario_input, hash_generado, hash_en_tabla, resultado)
        VALUES (p_username, v_hash_gen, v_hash_db, 'EXITO');
        COMMIT;
        RETURN TRUE;
    ELSE
        INSERT INTO GPROY_ELEL.LOG_AUTENTICACION_DEBUG (usuario_input, hash_generado, hash_en_tabla, resultado)
        VALUES (p_username, v_hash_gen, v_hash_db, 'HASH_DISTINTO');
        COMMIT;
        RETURN FALSE;
    END IF;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        INSERT INTO GPROY_ELEL.LOG_AUTENTICACION_DEBUG (usuario_input, resultado) VALUES (p_username, 'NO_EXISTE');
        COMMIT;
        RETURN FALSE;
    WHEN OTHERS THEN
        INSERT INTO GPROY_ELEL.LOG_AUTENTICACION_DEBUG (usuario_input, resultado) VALUES (p_username, 'ERROR_SQL');
        COMMIT;
        RETURN FALSE;
END;

